def retry(times=3, delay=0.5):
    def decorator(fn):
        @functools.wraps(fn)
        def wrapper(*args, **kwargs):
            for attempt in range(1, times + 1):
                try:
                    return fn(*args, **kwargs)
                except Exception:
                    if attempt == times:
                        raise
                    time.sleep(delay)
        return wrapper
    return decorator

import asyncio, functools

def retry(times=3, base=0.1):
    def deco(fn):
        @functools.wraps(fn)
        async def wrapper(*a, **k):
            for attempt in range(times):
                try:
                    return await fn(*a, **k)
                except Exception:
                    if attempt == times - 1:
                        raise
                    await asyncio.sleep(base * 2 ** attempt)
        return wrapper
    return deco

