def enforce(fn):
    sig = inspect.signature(fn)
    @functools.wraps(fn)
    def wrapper(*a, **k):
        bound = sig.bind(*a, **k)
        for name, value in bound.arguments.items():
            ann = sig.parameters[name].annotation
            if isinstance(ann, type) and not isinstance(value, ann):
                raise TypeError(f'{name} must be {ann.__name__}')
